INSERT OR IGNORE INTO academy_knowledge (id, kind, category, title_pl, title_en, content_pl, content_en, tags, source_ref) VALUES
('article:ARTICLE320-006','article','','Kolejność naprawy Windows po nieudanej aktualizacji','Windows recovery after a failed update','body: Kolejność naprawy Windows po nieudanej aktualizacji ZAKRES Nieudana aktualizacja może pozostawić system w rollback, uszkodzić konfigurację rozruchu lub wywołać niezgodność sterownika. TOK DIAGNOSTYCZNY Zapis kodu KB i błędu, sprawdzenie Release Health, kopia danych, WinRE, odinstalowanie aktualizacji tylko w razie potwierdzonej korelacji. STANDARDOWA KOLEJNOŚĆ 1. Identyfikacja modelu i rewizji. 2. Zapis objawu i historii. 3. Zabezpieczenie danych oraz zgoda. 4. Dokumentacja producenta i test bazowy. 5. Izolowanie jednej hipotezy naraz. 6. Działanie po potwierdzeniu przyczyny. 7. Test końcowy w tych samych warunkach. 8. Raport PASS/FAIL i ograniczenia. WAŻNE Wynik narzędzia nie jest automatycznie diagnozą. Zapisz warunki, wersje, źródła odniesienia oraz to, czego nie udało się przetestować. source: Akademia Serwisu PRO 3.2.0 — materiał redakcyjny z odwołaniem do dokumentacji producenta','bodyEn: Windows recovery after a failed update SCOPE A failed update may leave the system in rollback, damage boot configuration or expose a driver incompatibility. DIAGNOSTIC METHOD Record KB and error code, check Release Health, back up data, use WinRE and uninstall only when correlation is confirmed. STANDARD WORKFLOW 1. Identify model and revision. 2. Record symptom and history. 3. Protect data and obtain consent. 4. Check OEM documentation and baseline test. 5. Isolate one hypothesis at a time. 6. Act only after confirming the cause. 7. Run final test under the same conditions. 8. Issue a PASS/FAIL report with limitations. IMPORTANT A tool result is not automatically a diagnosis. Record conditions, versions, reference sources and anything that could not be tested.','','Akademia Serwisu PRO 3.2.0 — materiał redakcyjny z odwołaniem do dokumentacji producenta'),
('article:ARTICLE320-007','article','','Bezpieczne aktualizacje BIOS i firmware','Safe BIOS and firmware updates','body: Bezpieczne aktualizacje BIOS i firmware ZAKRES Firmware update może rozwiązać zgodność lub błąd, ale nie jest rutynowym pierwszym krokiem. Błędny plik lub utrata zasilania może unieruchomić urządzenie. TOK DIAGNOSTYCZNY Potwierdź exact model/SKU/revision, plik OEM, hash/podpis jeśli dostępny, zasilanie, kopię i klucz BitLocker. STANDARDOWA KOLEJNOŚĆ 1. Identyfikacja modelu i rewizji. 2. Zapis objawu i historii. 3. Zabezpieczenie danych oraz zgoda. 4. Dokumentacja producenta i test bazowy. 5. Izolowanie jednej hipotezy naraz. 6. Działanie po potwierdzeniu przyczyny. 7. Test końcowy w tych samych warunkach. 8. Raport PASS/FAIL i ograniczenia. WAŻNE Wynik narzędzia nie jest automatycznie diagnozą. Zapisz warunki, wersje, źródła odniesienia oraz to, czego nie udało się przetestować. source: Akademia Serwisu PRO 3.2.0 — materiał redakcyjny z odwołaniem do dokumentacji producenta','bodyEn: Safe BIOS and firmware updates SCOPE A firmware update may resolve compatibility or bugs, but it is not a routine first step. The wrong file or power loss may brick the device. DIAGNOSTIC METHOD Confirm exact model/SKU/revision, OEM file, hash/signature where available, power, backup and BitLocker key. STANDARD WORKFLOW 1. Identify model and revision. 2. Record symptom and history. 3. Protect data and obtain consent. 4. Check OEM documentation and baseline test. 5. Isolate one hypothesis at a time. 6. Act only after confirming the cause. 7. Run final test under the same conditions. 8. Issue a PASS/FAIL report with limitations. IMPORTANT A tool result is not automatically a diagnosis. Record conditions, versions, reference sources and anything that could not be tested.','','Akademia Serwisu PRO 3.2.0 — materiał redakcyjny z odwołaniem do dokumentacji producenta'),
('article:ARTICLE320-008','article','','Raport z pomiarów elektroniki płyty głównej','Motherboard electrical-measurement report','body: Raport z pomiarów elektroniki płyty głównej ZAKRES Pomiar ma wartość tylko wtedy, gdy znamy punkt, jednostkę, stan płyty, zakres miernika i źródło wartości odniesienia. TOK DIAGNOSTYCZNY Tabela pomiarów zawiera punkt, net name, polaryzację, zasilanie, temperaturę, miernik, wynik i źródło specyfikacji. STANDARDOWA KOLEJNOŚĆ 1. Identyfikacja modelu i rewizji. 2. Zapis objawu i historii. 3. Zabezpieczenie danych oraz zgoda. 4. Dokumentacja producenta i test bazowy. 5. Izolowanie jednej hipotezy naraz. 6. Działanie po potwierdzeniu przyczyny. 7. Test końcowy w tych samych warunkach. 8. Raport PASS/FAIL i ograniczenia. WAŻNE Wynik narzędzia nie jest automatycznie diagnozą. Zapisz warunki, wersje, źródła odniesienia oraz to, czego nie udało się przetestować. source: Akademia Serwisu PRO 3.2.0 — materiał redakcyjny z odwołaniem do dokumentacji producenta','bodyEn: Motherboard electrical-measurement report SCOPE A measurement is useful only when the point, unit, board state, meter range and reference source are known. DIAGNOSTIC METHOD A measurement table records point, net name, polarity, power state, temperature, meter, result and specification source. STANDARD WORKFLOW 1. Identify model and revision. 2. Record symptom and history. 3. Protect data and obtain consent. 4. Check OEM documentation and baseline test. 5. Isolate one hypothesis at a time. 6. Act only after confirming the cause. 7. Run final test under the same conditions. 8. Issue a PASS/FAIL report with limitations. IMPORTANT A tool result is not automatically a diagnosis. Record conditions, versions, reference sources and anything that could not be tested.','','Akademia Serwisu PRO 3.2.0 — materiał redakcyjny z odwołaniem do dokumentacji producenta'),
('article:ARTICLE320-009','article','','Weryfikacja USB4 i Thunderbolt w stacji dokującej','Validating USB4 and Thunderbolt docking','body: Weryfikacja USB4 i Thunderbolt w stacji dokującej ZAKRES Sama obudowa portu nie określa prędkości, wideo ani mocy. Zgodność zależy od hosta, kabla, docka i peryferiów. TOK DIAGNOSTYCZNY Testuj pojedynczo; sprawdź certyfikację kabla, obsługę hosta, firmware docka, liczbę ekranów i przepustowość. STANDARDOWA KOLEJNOŚĆ 1. Identyfikacja modelu i rewizji. 2. Zapis objawu i historii. 3. Zabezpieczenie danych oraz zgoda. 4. Dokumentacja producenta i test bazowy. 5. Izolowanie jednej hipotezy naraz. 6. Działanie po potwierdzeniu przyczyny. 7. Test końcowy w tych samych warunkach. 8. Raport PASS/FAIL i ograniczenia. WAŻNE Wynik narzędzia nie jest automatycznie diagnozą. Zapisz warunki, wersje, źródła odniesienia oraz to, czego nie udało się przetestować. source: Akademia Serwisu PRO 3.2.0 — materiał redakcyjny z odwołaniem do dokumentacji producenta','bodyEn: Validating USB4 and Thunderbolt docking SCOPE Port enclosure alone does not define speed, video or power. Compatibility depends on host, cable, dock and peripherals. DIAGNOSTIC METHOD Test one at a time; check cable certification, host support, dock firmware, display count and bandwidth. STANDARD WORKFLOW 1. Identify model and revision. 2. Record symptom and history. 3. Protect data and obtain consent. 4. Check OEM documentation and baseline test. 5. Isolate one hypothesis at a time. 6. Act only after confirming the cause. 7. Run final test under the same conditions. 8. Issue a PASS/FAIL report with limitations. IMPORTANT A tool result is not automatically a diagnosis. Record conditions, versions, reference sources and anything that could not be tested.','','Akademia Serwisu PRO 3.2.0 — materiał redakcyjny z odwołaniem do dokumentacji producenta'),
('article:ARTICLE320-010','article','','Postępowanie z baterią spuchniętą lub uszkodzoną','Handling a swollen or damaged battery','body: Postępowanie z baterią spuchniętą lub uszkodzoną ZAKRES Spuchnięcie oznacza uszkodzenie pakietu i ryzyko termiczne. Próba dalszego ładowania, dociskania lub przebijania jest niebezpieczna. TOK DIAGNOSTYCZNY Przerwij pracę, odłącz urządzenie bez naprężania baterii, zastosuj procedurę bezpieczeństwa i przekazania do właściwego recyklingu. STANDARDOWA KOLEJNOŚĆ 1. Identyfikacja modelu i rewizji. 2. Zapis objawu i historii. 3. Zabezpieczenie danych oraz zgoda. 4. Dokumentacja producenta i test bazowy. 5. Izolowanie jednej hipotezy naraz. 6. Działanie po potwierdzeniu przyczyny. 7. Test końcowy w tych samych warunkach. 8. Raport PASS/FAIL i ograniczenia. WAŻNE Wynik narzędzia nie jest automatycznie diagnozą. Zapisz warunki, wersje, źródła odniesienia oraz to, czego nie udało się przetestować. source: Akademia Serwisu PRO 3.2.0 — materiał redakcyjny z odwołaniem do dokumentacji producenta','bodyEn: Handling a swollen or damaged battery SCOPE Swelling indicates pack damage and thermal risk. Further charging, pressing or puncturing is dangerous. DIAGNOSTIC METHOD Stop work, disconnect the device without stressing the battery, follow safety procedure and transfer to proper recycling. STANDARD WORKFLOW 1. Identify model and revision. 2. Record symptom and history. 3. Protect data and obtain consent. 4. Check OEM documentation and baseline test. 5. Isolate one hypothesis at a time. 6. Act only after confirming the cause. 7. Run final test under the same conditions. 8. Issue a PASS/FAIL report with limitations. IMPORTANT A tool result is not automatically a diagnosis. Record conditions, versions, reference sources and anything that could not be tested.','','Akademia Serwisu PRO 3.2.0 — materiał redakcyjny z odwołaniem do dokumentacji producenta'),
('article:ARTICLE320-011','article','','Diagnostyka artefaktów GPU bez niepotrzebnego stress testu','GPU artifact diagnosis without unnecessary stress testing','body: Diagnostyka artefaktów GPU bez niepotrzebnego stress testu ZAKRES Artefakty mogą pochodzić z panelu, kabla, portu, VRAM, GPU, sterownika lub niestabilnego zasilania. Test obciążeniowy może pogorszyć sytuację. TOK DIAGNOSTYCZNY Test zewnętrzny ekran, zrzut, sterownik, temperaturę i logi. Użyj krótkiego testu dopiero po potwierdzeniu chłodzenia i zasilania. STANDARDOWA KOLEJNOŚĆ 1. Identyfikacja modelu i rewizji. 2. Zapis objawu i historii. 3. Zabezpieczenie danych oraz zgoda. 4. Dokumentacja producenta i test bazowy. 5. Izolowanie jednej hipotezy naraz. 6. Działanie po potwierdzeniu przyczyny. 7. Test końcowy w tych samych warunkach. 8. Raport PASS/FAIL i ograniczenia. WAŻNE Wynik narzędzia nie jest automatycznie diagnozą. Zapisz warunki, wersje, źródła odniesienia oraz to, czego nie udało się przetestować. source: Akademia Serwisu PRO 3.2.0 — materiał redakcyjny z odwołaniem do dokumentacji producenta','bodyEn: GPU artifact diagnosis without unnecessary stress testing SCOPE Artifacts can originate from panel, cable, port, VRAM, GPU, driver or unstable power. A stress test may make matters worse. DIAGNOSTIC METHOD Test external display, screenshot, driver, temperature and logs. Use a brief test only after confirming cooling and power. STANDARD WORKFLOW 1. Identify model and revision. 2. Record symptom and history. 3. Protect data and obtain consent. 4. Check OEM documentation and baseline test. 5. Isolate one hypothesis at a time. 6. Act only after confirming the cause. 7. Run final test under the same conditions. 8. Issue a PASS/FAIL report with limitations. IMPORTANT A tool result is not automatically a diagnosis. Record conditions, versions, reference sources and anything that could not be tested.','','Akademia Serwisu PRO 3.2.0 — materiał redakcyjny z odwołaniem do dokumentacji producenta'),
('article:ARTICLE320-012','article','','Diagnostyka ładowania USB-C na poziomie systemu i sprzętu','USB-C charging diagnosis across software and hardware','body: Diagnostyka ładowania USB-C na poziomie systemu i sprzętu ZAKRES Ładowanie zależy od adaptera, przewodu, portu, negocjacji PD, kontrolera, firmware i ograniczeń baterii. TOK DIAGNOSTYCZNY Zapis kontraktu PD, mocy znamionowej, temperatury złącza, komunikatów BIOS i testów na zgodnym zestawie. STANDARDOWA KOLEJNOŚĆ 1. Identyfikacja modelu i rewizji. 2. Zapis objawu i historii. 3. Zabezpieczenie danych oraz zgoda. 4. Dokumentacja producenta i test bazowy. 5. Izolowanie jednej hipotezy naraz. 6. Działanie po potwierdzeniu przyczyny. 7. Test końcowy w tych samych warunkach. 8. Raport PASS/FAIL i ograniczenia. WAŻNE Wynik narzędzia nie jest automatycznie diagnozą. Zapisz warunki, wersje, źródła odniesienia oraz to, czego nie udało się przetestować. source: Akademia Serwisu PRO 3.2.0 — materiał redakcyjny z odwołaniem do dokumentacji producenta','bodyEn: USB-C charging diagnosis across software and hardware SCOPE Charging depends on adapter, cable, port, PD negotiation, controller, firmware and battery limits. DIAGNOSTIC METHOD Record PD contract, rated power, connector temperature, BIOS messages and tests with a compatible setup. STANDARD WORKFLOW 1. Identify model and revision. 2. Record symptom and history. 3. Protect data and obtain consent. 4. Check OEM documentation and baseline test. 5. Isolate one hypothesis at a time. 6. Act only after confirming the cause. 7. Run final test under the same conditions. 8. Issue a PASS/FAIL report with limitations. IMPORTANT A tool result is not automatically a diagnosis. Record conditions, versions, reference sources and anything that could not be tested.','','Akademia Serwisu PRO 3.2.0 — materiał redakcyjny z odwołaniem do dokumentacji producenta'),
('article:ARTICLE320-013','article','','Ochrona prywatności w serwisie komputerowym','Privacy protection in a computer repair shop','body: Ochrona prywatności w serwisie komputerowym ZAKRES Serwis może mieć dostęp do dokumentów, kont, zdjęć, kopii i kluczy szyfrowania. Zasada minimalnego dostępu ogranicza ryzyko. TOK DIAGNOSTYCZNY Zgoda, minimalny zakres, lokalna analiza, anonimizacja raportu, bezpieczne przechowywanie kopii i potwierdzenie usunięcia według umowy. STANDARDOWA KOLEJNOŚĆ 1. Identyfikacja modelu i rewizji. 2. Zapis objawu i historii. 3. Zabezpieczenie danych oraz zgoda. 4. Dokumentacja producenta i test bazowy. 5. Izolowanie jednej hipotezy naraz. 6. Działanie po potwierdzeniu przyczyny. 7. Test końcowy w tych samych warunkach. 8. Raport PASS/FAIL i ograniczenia. WAŻNE Wynik narzędzia nie jest automatycznie diagnozą. Zapisz warunki, wersje, źródła odniesienia oraz to, czego nie udało się przetestować. source: Akademia Serwisu PRO 3.2.0 — materiał redakcyjny z odwołaniem do dokumentacji producenta','bodyEn: Privacy protection in a computer repair shop SCOPE Service staff may access documents, accounts, photos, backups and encryption keys. Least-privilege access reduces risk. DIAGNOSTIC METHOD Consent, minimum scope, local analysis, report anonymization, secure backup storage and deletion confirmation per agreement. STANDARD WORKFLOW 1. Identify model and revision. 2. Record symptom and history. 3. Protect data and obtain consent. 4. Check OEM documentation and baseline test. 5. Isolate one hypothesis at a time. 6. Act only after confirming the cause. 7. Run final test under the same conditions. 8. Issue a PASS/FAIL report with limitations. IMPORTANT A tool result is not automatically a diagnosis. Record conditions, versions, reference sources and anything that could not be tested.','','Akademia Serwisu PRO 3.2.0 — materiał redakcyjny z odwołaniem do dokumentacji producenta'),
('article:ARTICLE320-014','article','','Weryfikacja sieci Wi-Fi i routera z upoważnieniem','Authorized Wi-Fi and router validation','body: Weryfikacja sieci Wi-Fi i routera z upoważnieniem ZAKRES Problemy z Internetem mogą wynikać z DHCP, DNS, sygnału, kanałów, firmware, przewodu WAN lub awarii dostawcy. TOK DIAGNOSTYCZNY Test urządzenia referencyjnego, ping do bramy, DNS, DHCP lease, stan WAN i zalogowane błędy routera; zmiany po zgodzie właściciela. STANDARDOWA KOLEJNOŚĆ 1. Identyfikacja modelu i rewizji. 2. Zapis objawu i historii. 3. Zabezpieczenie danych oraz zgoda. 4. Dokumentacja producenta i test bazowy. 5. Izolowanie jednej hipotezy naraz. 6. Działanie po potwierdzeniu przyczyny. 7. Test końcowy w tych samych warunkach. 8. Raport PASS/FAIL i ograniczenia. WAŻNE Wynik narzędzia nie jest automatycznie diagnozą. Zapisz warunki, wersje, źródła odniesienia oraz to, czego nie udało się przetestować. source: Akademia Serwisu PRO 3.2.0 — materiał redakcyjny z odwołaniem do dokumentacji producenta','bodyEn: Authorized Wi-Fi and router validation SCOPE Internet issues may arise from DHCP, DNS, signal, channels, firmware, WAN cable or ISP outage. DIAGNOSTIC METHOD Test reference device, gateway ping, DNS, DHCP lease, WAN status and router logs; change settings only with owner approval. STANDARD WORKFLOW 1. Identify model and revision. 2. Record symptom and history. 3. Protect data and obtain consent. 4. Check OEM documentation and baseline test. 5. Isolate one hypothesis at a time. 6. Act only after confirming the cause. 7. Run final test under the same conditions. 8. Issue a PASS/FAIL report with limitations. IMPORTANT A tool result is not automatically a diagnosis. Record conditions, versions, reference sources and anything that could not be tested.','','Akademia Serwisu PRO 3.2.0 — materiał redakcyjny z odwołaniem do dokumentacji producenta'),
('article:ARTICLE320-015','article','','Kontrola jakości naprawy i przekazanie sprzętu','Repair quality control and customer handover','body: Kontrola jakości naprawy i przekazanie sprzętu ZAKRES Urządzenie powinno przejść test pierwotnego objawu oraz testy funkcji związanych z wykonaną naprawą. TOK DIAGNOSTYCZNY Raport zawiera zakres, część, numer katalogowy, wersje, wyniki, niewykonane testy, ograniczenia i zalecenia. STANDARDOWA KOLEJNOŚĆ 1. Identyfikacja modelu i rewizji. 2. Zapis objawu i historii. 3. Zabezpieczenie danych oraz zgoda. 4. Dokumentacja producenta i test bazowy. 5. Izolowanie jednej hipotezy naraz. 6. Działanie po potwierdzeniu przyczyny. 7. Test końcowy w tych samych warunkach. 8. Raport PASS/FAIL i ograniczenia. WAŻNE Wynik narzędzia nie jest automatycznie diagnozą. Zapisz warunki, wersje, źródła odniesienia oraz to, czego nie udało się przetestować. source: Akademia Serwisu PRO 3.2.0 — materiał redakcyjny z odwołaniem do dokumentacji producenta','bodyEn: Repair quality control and customer handover SCOPE The device should pass the original symptom test and function tests related to the repair. DIAGNOSTIC METHOD The report includes scope, part, part number, versions, results, skipped tests, limitations and recommendations. STANDARD WORKFLOW 1. Identify model and revision. 2. Record symptom and history. 3. Protect data and obtain consent. 4. Check OEM documentation and baseline test. 5. Isolate one hypothesis at a time. 6. Act only after confirming the cause. 7. Run final test under the same conditions. 8. Issue a PASS/FAIL report with limitations. IMPORTANT A tool result is not automatically a diagnosis. Record conditions, versions, reference sources and anything that could not be tested.','','Akademia Serwisu PRO 3.2.0 — materiał redakcyjny z odwołaniem do dokumentacji producenta'),
('article:ARTICLE320-016','article','','Dokumentacja producenta jako punkt odniesienia','Using OEM documentation as the reference','body: Dokumentacja producenta jako punkt odniesienia ZAKRES Procedury, złącza, momenty dokręcania i części różnią się między modelami oraz rewizjami. Nie istnieje uniwersalny schemat dla wszystkich laptopów. TOK DIAGNOSTYCZNY Wyszukaj po pełnym modelu i numerze produktu, potwierdź rewizję i archiwizuj datę sprawdzenia źródła. STANDARDOWA KOLEJNOŚĆ 1. Identyfikacja modelu i rewizji. 2. Zapis objawu i historii. 3. Zabezpieczenie danych oraz zgoda. 4. Dokumentacja producenta i test bazowy. 5. Izolowanie jednej hipotezy naraz. 6. Działanie po potwierdzeniu przyczyny. 7. Test końcowy w tych samych warunkach. 8. Raport PASS/FAIL i ograniczenia. WAŻNE Wynik narzędzia nie jest automatycznie diagnozą. Zapisz warunki, wersje, źródła odniesienia oraz to, czego nie udało się przetestować. source: Akademia Serwisu PRO 3.2.0 — materiał redakcyjny z odwołaniem do dokumentacji producenta','bodyEn: Using OEM documentation as the reference SCOPE Procedures, connectors, torque values and parts vary by model and revision. There is no universal schematic for all laptops. DIAGNOSTIC METHOD Search by complete model and product number, confirm revision and archive the date the source was checked. STANDARD WORKFLOW 1. Identify model and revision. 2. Record symptom and history. 3. Protect data and obtain consent. 4. Check OEM documentation and baseline test. 5. Isolate one hypothesis at a time. 6. Act only after confirming the cause. 7. Run final test under the same conditions. 8. Issue a PASS/FAIL report with limitations. IMPORTANT A tool result is not automatically a diagnosis. Record conditions, versions, reference sources and anything that could not be tested.','','Akademia Serwisu PRO 3.2.0 — materiał redakcyjny z odwołaniem do dokumentacji producenta'),
('article:ARTICLE320-017','article','','Diagnoza problemów z kamerą, mikrofonem i czujnikami','Camera, microphone and sensor diagnostics','body: Diagnoza problemów z kamerą, mikrofonem i czujnikami ZAKRES Problem z kamerą lub mikrofonem może wynikać z uprawnień, przesłony, sterownika, taśmy albo modułu. TOK DIAGNOSTYCZNY Test aplikacji referencyjnej, uprawnień, prywatności, Menedżera urządzeń i urządzenia zewnętrznego. STANDARDOWA KOLEJNOŚĆ 1. Identyfikacja modelu i rewizji. 2. Zapis objawu i historii. 3. Zabezpieczenie danych oraz zgoda. 4. Dokumentacja producenta i test bazowy. 5. Izolowanie jednej hipotezy naraz. 6. Działanie po potwierdzeniu przyczyny. 7. Test końcowy w tych samych warunkach. 8. Raport PASS/FAIL i ograniczenia. WAŻNE Wynik narzędzia nie jest automatycznie diagnozą. Zapisz warunki, wersje, źródła odniesienia oraz to, czego nie udało się przetestować. source: Akademia Serwisu PRO 3.2.0 — materiał redakcyjny z odwołaniem do dokumentacji producenta','bodyEn: Camera, microphone and sensor diagnostics SCOPE Camera or microphone issues may arise from permissions, privacy shutter, driver, cable or module. DIAGNOSTIC METHOD Test a reference application, permissions, privacy settings, Device Manager and an external device. STANDARD WORKFLOW 1. Identify model and revision. 2. Record symptom and history. 3. Protect data and obtain consent. 4. Check OEM documentation and baseline test. 5. Isolate one hypothesis at a time. 6. Act only after confirming the cause. 7. Run final test under the same conditions. 8. Issue a PASS/FAIL report with limitations. IMPORTANT A tool result is not automatically a diagnosis. Record conditions, versions, reference sources and anything that could not be tested.','','Akademia Serwisu PRO 3.2.0 — materiał redakcyjny z odwołaniem do dokumentacji producenta'),
('article:ARTICLE320-018','article','','Zarządzanie wersjami sterowników w serwisie','Driver-version management in a repair shop','body: Zarządzanie wersjami sterowników w serwisie ZAKRES Aktualizacja sterownika wymaga zapisu wersji początkowej, źródła instalacji i sposobu wycofania. TOK DIAGNOSTYCZNY Zapisz identyfikator urządzenia, wersję, datę i producenta. Testuj po jednym pakiecie oraz zachowaj możliwość rollback. STANDARDOWA KOLEJNOŚĆ 1. Identyfikacja modelu i rewizji. 2. Zapis objawu i historii. 3. Zabezpieczenie danych oraz zgoda. 4. Dokumentacja producenta i test bazowy. 5. Izolowanie jednej hipotezy naraz. 6. Działanie po potwierdzeniu przyczyny. 7. Test końcowy w tych samych warunkach. 8. Raport PASS/FAIL i ograniczenia. WAŻNE Wynik narzędzia nie jest automatycznie diagnozą. Zapisz warunki, wersje, źródła odniesienia oraz to, czego nie udało się przetestować. source: Akademia Serwisu PRO 3.2.0 — materiał redakcyjny z odwołaniem do dokumentacji producenta','bodyEn: Driver-version management in a repair shop SCOPE Driver updates require recording baseline version, installation source and rollback method. DIAGNOSTIC METHOD Record device ID, version, date and provider. Test one package at a time and preserve rollback. STANDARD WORKFLOW 1. Identify model and revision. 2. Record symptom and history. 3. Protect data and obtain consent. 4. Check OEM documentation and baseline test. 5. Isolate one hypothesis at a time. 6. Act only after confirming the cause. 7. Run final test under the same conditions. 8. Issue a PASS/FAIL report with limitations. IMPORTANT A tool result is not automatically a diagnosis. Record conditions, versions, reference sources and anything that could not be tested.','','Akademia Serwisu PRO 3.2.0 — materiał redakcyjny z odwołaniem do dokumentacji producenta'),
('article:ARTICLE320-019','article','','Odzyskiwanie systemu plików a obraz nośnika','Filesystem recovery versus drive imaging','body: Odzyskiwanie systemu plików a obraz nośnika ZAKRES Naprawa logiczna systemu plików modyfikuje dane. Przy niestabilnym nośniku bezpieczniej analizować obraz roboczy. TOK DIAGNOSTYCZNY Oceń kondycję, wykonaj obraz, zweryfikuj kopię, dopiero potem testuj narzędzia naprawcze na kopii. STANDARDOWA KOLEJNOŚĆ 1. Identyfikacja modelu i rewizji. 2. Zapis objawu i historii. 3. Zabezpieczenie danych oraz zgoda. 4. Dokumentacja producenta i test bazowy. 5. Izolowanie jednej hipotezy naraz. 6. Działanie po potwierdzeniu przyczyny. 7. Test końcowy w tych samych warunkach. 8. Raport PASS/FAIL i ograniczenia. WAŻNE Wynik narzędzia nie jest automatycznie diagnozą. Zapisz warunki, wersje, źródła odniesienia oraz to, czego nie udało się przetestować. source: Akademia Serwisu PRO 3.2.0 — materiał redakcyjny z odwołaniem do dokumentacji producenta','bodyEn: Filesystem recovery versus drive imaging SCOPE Filesystem repair modifies data. With unstable media, it is safer to analyze a working image. DIAGNOSTIC METHOD Assess media health, create and verify an image, then test repair tools on a copy. STANDARD WORKFLOW 1. Identify model and revision. 2. Record symptom and history. 3. Protect data and obtain consent. 4. Check OEM documentation and baseline test. 5. Isolate one hypothesis at a time. 6. Act only after confirming the cause. 7. Run final test under the same conditions. 8. Issue a PASS/FAIL report with limitations. IMPORTANT A tool result is not automatically a diagnosis. Record conditions, versions, reference sources and anything that could not be tested.','','Akademia Serwisu PRO 3.2.0 — materiał redakcyjny z odwołaniem do dokumentacji producenta'),
('article:ARTICLE320-020','article','','Metody diagnozy zasilacza bez ingerencji w sekcję sieciową','Power-supply diagnosis without mains-side work','body: Metody diagnozy zasilacza bez ingerencji w sekcję sieciową ZAKRES Zewnętrzne testy obejmują przewód, gniazdo, zgodne urządzenie referencyjne i tester używany zgodnie z instrukcją. TOK DIAGNOSTYCZNY Nie otwieraj zasilacza. Porównuj wyniki na sprawnym zasilaczu o prawidłowej mocy. STANDARDOWA KOLEJNOŚĆ 1. Identyfikacja modelu i rewizji. 2. Zapis objawu i historii. 3. Zabezpieczenie danych oraz zgoda. 4. Dokumentacja producenta i test bazowy. 5. Izolowanie jednej hipotezy naraz. 6. Działanie po potwierdzeniu przyczyny. 7. Test końcowy w tych samych warunkach. 8. Raport PASS/FAIL i ograniczenia. WAŻNE Wynik narzędzia nie jest automatycznie diagnozą. Zapisz warunki, wersje, źródła odniesienia oraz to, czego nie udało się przetestować. source: Akademia Serwisu PRO 3.2.0 — materiał redakcyjny z odwołaniem do dokumentacji producenta','bodyEn: Power-supply diagnosis without mains-side work SCOPE External tests include the cable, outlet, compatible reference device and tester used according to instructions. DIAGNOSTIC METHOD Do not open the PSU. Compare results using a known-good unit with correct ratings. STANDARD WORKFLOW 1. Identify model and revision. 2. Record symptom and history. 3. Protect data and obtain consent. 4. Check OEM documentation and baseline test. 5. Isolate one hypothesis at a time. 6. Act only after confirming the cause. 7. Run final test under the same conditions. 8. Issue a PASS/FAIL report with limitations. IMPORTANT A tool result is not automatically a diagnosis. Record conditions, versions, reference sources and anything that could not be tested.','','Akademia Serwisu PRO 3.2.0 — materiał redakcyjny z odwołaniem do dokumentacji producenta'),
('manual:MANUAL-11','manual','','Schemat serwisowy Quanta ZGR / ZGRC (DAZGRMB2AC0) — boardview','','body: Schemat serwisowy Quanta ZGR / ZGRC (DAZGRMB2AC0) — boardview source: Podręcznik serwisowy – 161 stron','','','Podręcznik serwisowy – 161 stron'),
('manual:MANUAL-01','manual','','Budowa laptopa i komputera — mapa elementów','','body: elementów Rys. 1. Budowa laptopa i komputera — mapa elementów Zanim cokolwiek naprawisz, musisz wiedzieć co widzisz na płycie. Ten rozdział to mapa najważniejszych podzespołów i ich rola w torze zasilania oraz sygnałów. Procedura krok po kroku • Płyta główna (mainboard) — łączy wszystkie podzespoły, prowadzi zasilanie i magistrale danych. • Procesor (CPU) + sekcja VRM — zasilanie rdzenia: cewki, tranzystory MOSFET i kontroler PWM. • Pamięć RAM (SODIMM/DIMM) i sloty — przy braku obrazu pierwszy podejrzany. • Sekcja ładowania — kontroler charging IC + gniazdo DC-IN; zamienia 19–20 V na napięcia systemowe. • EC (Embedded Controller) + BIOS SPI — pilnują sekwencji włączania (mózg startu). • Chłodzenie: heatpipe + radiator + wentylator; złącza matrycy, klawiatury i baterii. Jak robić pomiary • Zlokalizuj duże cewki zasilania — przy nich mierzy się VCORE / 3,3 V / 5 V. • Odszukaj kontroler ładowania (np. z serii BQ24…) obok gniazda DC-IN. Jak wykrywać usterki • Brak podzespołu lub odklejone złącze = brak startu. • Ślady zalania (biały/zielony nalot) = utlenione ścieżki — częsta przyczyna awarii. Wskazówka serwisowa: Zrób zdjęcie płyty PRZED demontażem — ułatwi złożenie i pokaże, gdzie szły taśmy i złącza. source: Podręcznik serwisowy – 161 stron','','','Podręcznik serwisowy – 161 stron'),
('manual:MANUAL-02','manual','','Sekcja zasilania i ładowania (DC-IN, charging IC)','','body: charging IC) Rys. 2. Sekcja zasilania i ładowania (DC-IN, charging IC) Najczęstsza usterka: laptop nie ładuje lub nie włącza się z zasilacza. Idziemy krok po kroku po torze zasilania. Procedura krok po kroku • Zmierz napięcie na wtyku zasilacza: 19–20 V (laptop). Brak = zasilacz lub kabel. • Za gniazdem DC-IN sprawdź, czy 19 V dochodzi do kondensatora wejściowego sekcji ładowania. • Sprawdź bezpiecznik SMD przy gnieździe (ciągłość ~0 Ω). Przepalony = brak zasilania dalej. • Kontroler ładowania generuje sygnały ACOK/ACIN i napięcie do systemu — mierz jego wejścia i wyjścia. • Napięcia standby 3,3 V / 5 V (ALW) muszą być OBECNE zaraz po podłączeniu, przed wciśnięciem power. Jak robić pomiary • DC 20 V na wtyku i za gniazdem DC-IN. • Ciągłość bezpiecznika wejściowego (brzęczyk). • 3,3 V_ALW i 5 V_ALW na cewkach standby. • Sygnał EN/PWRON do przetwornic. Jak wykrywać usterki • Brak 19 V za gniazdem = zimny lut / uszkodzone gniazdo. • Jest 19 V, brak standby = zwarcie na linii lub uszkodzony charging IC. • Ładuje tylko po dociśnięciu wtyczki = mechaniczne uszkodzenie gniazda. Wskazówka serwisowa: Zasilacz laboratoryjny z limitem prądu to najlepszy przyjaciel serwisu — od razu widzisz pobór i zwarcia. source: Podręcznik serwisowy – 161 stron','','','Podręcznik serwisowy – 161 stron'),
('manual:MANUAL-03','manual','','VRM — zasilanie rdzenia CPU/GPU','','body: Rys. 3. VRM — zasilanie rdzenia CPU/GPU VRM zamienia 12 V / 5 V na precyzyjne ~1 V dla rdzenia. Uszkodzona faza = brak startu lub restart pod obciążeniem. Procedura krok po kroku • Zidentyfikuj fazy: cewka + para MOSFET (górny/dolny) + kontroler PWM. • Zmierz VIN faz (zwykle 12 V lub 5 V) oraz VCORE po starcie (0,6–1,3 V zależnie od CPU). • Sprawdź sygnał PWM/EN z kontrolera — bez niego fazy nie ruszą. • Termowizja: przegrzany MOSFET = zwarty tranzystor. Jak robić pomiary • VIN faz do masy (Ω) — bardzo niska rezystancja = zwarty MOSFET. • VCORE po komendzie startu. • Napięcie bramki (gate) MOSFET-ów. Jak wykrywać usterki • Zwarty dolny MOSFET = zwarcie VCORE do masy = zasilacz się wyłącza. • Uszkodzony kontroler PWM = brak VCORE mimo dobrych MOSFET-ów. Wskazówka serwisowa: MOSFET-y wymieniaj parami i zawsze sprawdź kontroler — spalony tranzystor często zabiera driver ze sobą. source: Podręcznik serwisowy – 161 stron','','','Podręcznik serwisowy – 161 stron'),
('manual:MANUAL-04','manual','','Wykrywanie i lokalizacja zwarć','','body: Rys. 4. Wykrywanie i lokalizacja zwarć Zwarcie = zasilacz się wyłącza lub płyta grzeje w jednym miejscu. Trzeba precyzyjnie zlokalizować winowajcę. Procedura krok po kroku • Tryb rezystancji: zmierz linie do masy. Zdrowe VCORE kilka–kilkadziesiąt Ω; ~0 Ω = zwarcie. • Metoda wstrzykiwania: podaj 3–5 V (z limitem prądu) na zwartą linię. • Kamera termowizyjna lub palec — grzejący element to zwarty kondensator / MOSFET / układ. • Alkohol izopropylowy odparuje najszybciej nad zwartym elementem. • Zdejmij podejrzany element i zmierz ponownie — zwarcie znika = to był on. Jak robić pomiary • Rezystancja linii VCORE / 3,3 V / 5 V / 1,8 V do masy. • Porównaj z drugą stroną, jeśli układ jest symetryczny. Jak wykrywać usterki • Pęknięty kondensator MLCC po upadku/zalaniu (najczęstsze). • Zwarty MOSFET sekcji zasilania. • Uszkodzony układ scalony po przepięciu. Wskazówka serwisowa: Nie wymieniaj od razu wszystkiego — najpierw ZLOKALIZUJ zwarcie, potem usuwaj konkretny element. source: Podręcznik serwisowy – 161 stron','','','Podręcznik serwisowy – 161 stron'),
('manual:MANUAL-05','manual','','Pomiary multimetrem — napięcia, ciągłość, dioda','','body: dioda Rys. 5. Pomiary multimetrem — napięcia, ciągłość, dioda Multimetr to podstawowe narzędzie serwisu. Trzy tryby rozwiązują ok. 80% diagnoz. Procedura krok po kroku • Napięcie DC (V ): czarna sonda na masę, czerwona na punkt pomiaru; zakres 20 V. • Ciągłość / brzęczyk: bezpieczniki, ścieżki, przerwy. Brzęczy = połączenie jest. • Test diody: sprawdza złącza półprzewodnikowe (diody, MOSFET-y) — kierunek przewodzenia. • Rezystancja (Ω): pomiar do masy w poszukiwaniu zwarć i przerw. Jak robić pomiary • Masa = metalowa osłona USB, śruby montażowe, minus baterii. • Najpierw sprawdź multimetr — zewrzyj sondy, powinien brzęczeć. Jak wykrywać usterki • Błędny zakres = złe odczyty. • Pomiar rezystancji na zasilanej płycie = błąd i ryzyko uszkodzenia. Wskazówka serwisowa: Rezystancję i ciągłość mierz ZAWSZE na odłączonym zasilaniu; napięcia — na włączonym. source: Podręcznik serwisowy – 161 stron','','','Podręcznik serwisowy – 161 stron'),
('manual:MANUAL-06','manual','','Chłodzenie, pasta termiczna i temperatury','','body: Rys. 6. Chłodzenie, pasta termiczna i temperatury Przegrzewanie i wyłączanie (throttling) to najczęstszy problem laptopów po 1–2 latach. Procedura krok po kroku • Rozkręć układ chłodzenia po przekątnej, równomiernie — nie wygnij rdzenia. • Usuń starą pastę alkoholem izopropylowym z rdzenia i podstawy heatpipe. • Nałóż nową pastę (ziarno ryżu) — docisk rozprowadzi ją równomiernie. • Przedmuchaj lamele radiatora, przytrzymując wentylator. • Sprawdź temperatury NA ŻYWO w monitorze aplikacji (agent + test wydajności). Jak robić pomiary • Temperatura CPU/GPU w spoczynku i pod obciążeniem. • Obroty wentylatora (RPM) — 0 RPM = uszkodzony wentylator. Jak wykrywać usterki • Zaschnięta pasta + zapchany radiator = throttling i wyłączenia. • Uszkodzony wentylator lub czujnik temperatury = alarm i shutdown. Wskazówka serwisowa: Do mocnych układów używaj pasty ≥ 8 W/mK. W laptopach gamingowych rozważ metal ciekły (ostrożnie). source: Podręcznik serwisowy – 161 stron','','','Podręcznik serwisowy – 161 stron'),
('manual:MANUAL-07','manual','','Pamięć RAM i brak obrazu (POST)','','body: Rys. 7. Pamięć RAM i brak obrazu (POST) Włącza się, wentylatory kręcą, ale nie ma obrazu. Diagnozujemy metodycznie. Procedura krok po kroku • Wyjmij RAM, wyczyść styki, włóż jedną kość i testuj po kolei każdy slot. • Podłącz monitor do właściwego wyjścia (dedykowana GPU, nie płyta). • Odczytaj kody POST: piszczyk lub diody Debug LED (CPU/DRAM/VGA/BOOT). • Zresetuj BIOS (bateria CMOS / zworka CLR_CMOS). • Test minimum: CPU + 1× RAM + zasilanie, bez dysków i kart. Jak robić pomiary • Napięcie RAM (DDR4 1,2 V / DDR5 1,1 V) na slotach. • Sygnał zegara pamięci (oscyloskop — dla zaawansowanych). Jak wykrywać usterki • Dioda DRAM świeci = problem pamięci lub kontrolera w CPU. • Dioda VGA = karta / GPU. • Brak jakiejkolwiek reakcji = zasilanie / EC / BIOS. Wskazówka serwisowa: Czyszczenie styków RAM gumką + alkohol rozwiązuje zaskakująco dużo „braków obrazu”. source: Podręcznik serwisowy – 161 stron','','','Podręcznik serwisowy – 161 stron'),
('manual:MANUAL-08','manual','','Dyski, SMART i odzyskiwanie danych','','body: Rys. 8. Dyski, SMART i odzyskiwanie danych Zasada nr 1: najpierw kopia danych, potem naprawa. Uszkodzony dysk może paść całkiem w każdej chwili. Procedura krok po kroku • Podłącz dysk przez adapter USB-SATA/NVMe do sprawnego komputera (nie instaluj na nim systemu). • Sprawdź SMART (CrystalDiskInfo) — relokowane/oczekujące sektory = dysk umiera. • Kopiuj od najcenniejszych plików (dokumenty, zdjęcia) zanim padnie. • Klikanie / nietypowe dźwięki = uszkodzenie mechaniczne HDD — do laboratorium data recovery. • Dopiero po kopii próbuj naprawy systemu (chkdsk, naprawa startu). Jak robić pomiary • Napięcia 5 V i 12 V zasilania dysku (HDD 3,5"). • Wykrywanie w BIOS/UEFI. Jak wykrywać usterki • Zły stan SMART (Reallocated/Pending sectors). • Kontroler SSD „znika” po przegrzaniu. • Uszkodzony blok rozruchowy = system nie startuje, dane wciąż są. Wskazówka serwisowa: Nigdy nie uruchamiaj chkdsk /f na słabnącym dysku PRZED backupem — może dobić sektory. source: Podręcznik serwisowy – 161 stron','','','Podręcznik serwisowy – 161 stron'),
('manual:MANUAL-09','manual','','Matryca, podświetlenie i taśma eDP/LVDS','','body: Rys. 9. Matryca, podświetlenie i taśma eDP/LVDS Ciemny ekran, ale obraz widać pod latarką? To podświetlenie. Pęknięcia/pasy? Matryca lub taśma. Procedura krok po kroku • Podświetl ekran latarką pod kątem — jeśli widać pulpit, problem to podświetlenie/przetwornica. • Podłącz zewnętrzny monitor — obraz jest = uszkodzona matryca/taśma; brak = GPU/płyta. • Sprawdź taśmę eDP/LVDS i złącze przy zawiasie (przetarcia od otwierania). • Dobierz matrycę po oznaczeniu z tyłu (np. B156HAN…) — zwróć uwagę na złącze i rozdzielczość. Jak robić pomiary • Napięcie zasilania matrycy (zwykle 3,3 V) na złączu. • Sygnał podświetlenia (BL_EN, PWM). Jak wykrywać usterki • Pasy/plamy/rozbita matryca = wymiana panelu. • Ciemny ekran + obraz pod latarką = podświetlenie/przetwornica. • Migotanie przy ruchu klapą = przetarta taśma. Wskazówka serwisowa: Przy wymianie matrycy odłącz baterię i rozładuj się z ładunków — panele są wrażliwe na ESD. source: Podręcznik serwisowy – 161 stron','','','Podręcznik serwisowy – 161 stron'),
('manual:MANUAL-10','manual','','Lutowanie SMD i podstawy BGA / reballing','','body: Rys. 10. Lutowanie SMD i podstawy BGA / reballing Najtrudniejszy poziom: praca z układami BGA (chipset, GPU, mostki). Wymaga wprawy i sprzętu. Procedura krok po kroku • Podgrzej płytę na preheaterze (120–150 °C), by zmniejszyć naprężenia i szok termiczny. • Hot-air 380–400 °C z topnikiem — równomiernie, ruchem okrężnym, obserwuj rozpływ. • Zdejmij układ pęsetą gdy cyna się rozpłynie (nie szarp na zimno). • Oczyść pady, nałóż nową cynę, wykonaj reballing (szablon + kulki BGA). • Ułóż układ, podgrzej do rozpływu, sprawdź spoiny mikroskopem. Jak robić pomiary • Ciągłość pinów zasilania układu do padów po lutowaniu. • Temperatura płyty (termopara / kamera). Jak wykrywać usterki • Zimne luty = niestabilna praca, restarty. • Przegrzanie = uszkodzenie kryształu / płyty. • Źle wykonany reballing = zwarcia między kulkami. Wskazówka serwisowa: Zacznij od ćwiczeń na złomie. BGA bez preheatera i wprawy to prosta droga do zniszczenia płyty. 11. Schemat serwisowy Quanta ZGR Na kolejnych stronach znajduje się pełny schemat serwisowy (boardview) płyty głównej Quanta ZGR / ZGRC (DAZGRMB2AC0): rozkład elementów, punkty pomiarowe, napięcia i sygnały. Korzystaj z niego razem z rozdziałami o zasilaniu, VRM i lokalizacji zwarć. 5 4 3 2 1 2023 RPL Block Diagram (Roadster - ZGRC/ ZGRE) 1 SODIMM1 DDR5 4800MHz VBIOS HDMI Conn. Max. 32GB Reverse PG.21 16M PG.30 PG.49 Channel A SODIMM2 Max. 32GB Standard PG.22 DDR5 4800MHz Raptor lake-HX SPI HDMI + Channel B D PCIe X8 NVIDIA VRAM D GN20-E3 256M x 16 X 6 pcs gDDR6 PCH GN21/WN21-MB1 GB5B-256 GN20-E5/E6/E7 256M x 16 X 8 pcs gDDR6 PCIe SSD PCIe Gen4 x4 GN20-P1 256M x 16 x 4pcs gDDR6 PG.38~41 M.2 2280 PG.25 ~37 PG.53 PG.2 ~15 DDS eDP PCIe SSD PCIe Gen4 x4 eDP M.2 2280 eDP Mux PG.44 Panel Conn. PG.45 PG.55 PI3DPX8121ZLDEX USB2 U2-P2,P10 TCP0 Thunderbolt Re-timer Type C Conn. DMIC Audio HDA Intel Maple-Ridge PG.76~77 SMBUs JHL8540-QUBZ PG.45 PG.64 PG.72~74 ALC3324 SM